def make_invoice(amounts):
    # Exact type check: only a plain list is accepted (not str, tuple, None, ...).
    if type(amounts) is not list:
        raise ValueError("amounts must be a list")
    # Summing integer cents is exact and independent of the decimal context.
    total_cents = 0
